from pathlib import Path
import base64,json

out=Path(__file__).resolve().parent
font=base64.b64encode((out/'fonts/Fraunces.woff2').read_bytes()).decode()
glyphs={
 'broadcast': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="3.1" stroke-linecap="round" stroke-linejoin="round"><path d="M5 9Q20-2 35 9M11 15q9-7 18 0M4 21q8-3 16 3 8-6 16-3v13q-8-3-16 3-8-6-16-3V21Zm16 3v13"/></g></svg>',
 'pages': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="3.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10q8-5 16 2 8-7 16-2M5 18q8-4 15 3 7-7 15-3M7 26q7-2 13 4 6-6 13-4"/></g><circle cx="20" cy="36" r="2.3" fill="currentColor"/></svg>',
 'open': '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40" aria-hidden="true"><path d="M4 10Q20-2 36 10L32 15Q20 6 8 15ZM10 20q10-8 20 0l-4 5q-6-5-12 0Z" fill="currentColor"/><path d="M18 28q-5-4-11-3v9q6-1 11 4ZM22 28q5-4 11-3v9q-6-1-11 4Z" fill="currentColor"/></svg>',
}
options=[
 ('broadcast','01','Broadcast book','The clearest combination','Two signal arcs rise from an open book. The book’s central fold anchors the symbol; the signal suggests knowledge being shared.'),
 ('pages','02','Wave pages','The most integrated','The signal bands bend into pairs of open pages. One repeated form does both jobs, though the Wi-Fi reference is less literal.'),
 ('open','03','Open signal','The boldest at small sizes','An open book replaces the dot at the base of the Wi-Fi signal. Solid shapes keep the superscript legible in a small header.'),
]
for key,svg in glyphs.items():
 (out/f'glyph-{key}.svg').write_text(svg.replace('aria-hidden="true"','role="img" aria-label="Book and wireless signal glyph"').replace('currentColor','#1c3b2e'))
def mark(key='broadcast',cls=''):
 return f'<span class="mark {cls}" role="img" aria-label="hiraia">hiraia<span class="glyph" data-glyph>{glyphs[key]}</span></span>'
cards=''
for key,n,name,tag,desc in options:
 cards+=f'<button class="option {"selected" if key=="broadcast" else ""}" data-option="{key}" aria-pressed="{str(key=="broadcast").lower()}"><span class="eyebrow">{n} / {name}</span><span class="icon-study">{glyphs[key]}</span><span class="word-study">{mark(key)}</span><span class="tag">{tag}</span><span class="description">{desc}</span><span class="small-study">{mark(key,"small")}<span class="size-label">32px type</span></span><span class="choose">Try this glyph ↗</span></button>'
css='''
*{box-sizing:border-box}body{--ink:#1c3b2e;--paper:#f5ecd6;--gold:#bd8928;--glyph-size:.34em;--glyph-rise:-.44em;margin:0;background:var(--paper);color:var(--ink);font-family:system-ui,-apple-system,sans-serif}main{max-width:1230px;padding:36px 38px;margin:auto}.top{display:flex;align-items:center;justify-content:space-between;padding-bottom:20px;border-bottom:1px solid #1c3b2e33}.mini{font:32px Fraunces;letter-spacing:-.027em}.eyebrow{font-size:10px;letter-spacing:.12em;text-transform:uppercase}.top p{font-size:12px;color:#5b6e5f;margin:5px 0 0}h1{font-size:33px;font-weight:500;letter-spacing:-.035em;margin:29px 0 12px}.intro{max-width:750px;color:#506354;font-size:15px;line-height:1.6;margin:0 0 25px}.options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}button{font:inherit;color:inherit;cursor:pointer;background:transparent}button:focus-visible{outline:3px solid #bd8928;outline-offset:4px}.option{border:1px solid #1c3b2e44;border-radius:8px;text-align:left;display:block;min-width:0;padding:19px 20px}.option.selected{box-shadow:inset 0 0 0 1px var(--ink);border-color:var(--ink)}.option>.eyebrow{display:block}.icon-study{display:block;width:68px;height:68px;margin:24px auto 0;color:var(--ink)}svg{display:block;width:100%;height:100%}.word-study{display:flex;justify-content:center;align-items:center;height:135px}.mark{display:inline-flex;align-items:baseline;font:400 78px/1 Fraunces;letter-spacing:-.027em;white-space:nowrap}.glyph{width:var(--glyph-size);height:var(--glyph-size);display:inline-block;position:relative;top:var(--glyph-rise);margin-left:.068em;color:var(--gold);flex-shrink:0}.tag{font-size:17px;letter-spacing:-.02em;font-weight:550;display:block;margin:0 0 9px}.description{font-size:13px;line-height:1.65;color:#506354;display:block;min-height:87px}.small-study{display:flex;justify-content:space-between;align-items:baseline;border-top:1px solid #1c3b2e22;padding-top:20px;margin-top:13px}.mark.small{font-size:32px}.size-label{font-size:10px;color:#58705f}.choose{display:block;font-size:11px;color:#58705f;margin-top:19px}.controls{display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin:24px 0}.controls button{font-size:12px;padding:8px 13px;border:1px solid #1c3b2e55;border-radius:24px}.controls label{font-size:12px;display:flex;align-items:center;gap:9px}input{accent-color:#1c3b2e;width:110px}.tryout{display:grid;grid-template-columns:1fr 1fr;gap:20px}.context{border:1px solid #1c3b2e33;border-radius:8px;padding:25px 28px;min-height:206px}.dark{background:var(--ink);color:var(--paper)}.dark .glyph{color:inherit}.context .mark{font-size:76px;margin-top:30px}.context p{font-size:12px;line-height:1.6;opacity:.75;margin:18px 0 0}.nav{display:flex;justify-content:space-between;align-items:baseline;gap:16px}.nav .mark{font-size:32px}.nav>span:last-child{font-size:12px}.status{font-size:13px;color:#506354;margin:20px 0 13px}footer{font-size:12px;line-height:1.65;color:#5b6e5f;border-top:1px solid #1c3b2e33;margin-top:27px;padding-top:18px}footer a{color:inherit}.mono .glyph{color:inherit}@media(max-width:1000px){.options{gap:12px}.option{padding:17px 15px}.mark{font-size:67px}.description{min-height:108px}}@media(max-width:800px){main{padding:26px 22px}.options,.tryout{grid-template-columns:1fr}.description{min-height:0}.mark{font-size:85px}.word-study{height:138px}.icon-study{margin-top:25px}.top{gap:16px}h1{font-size:29px}.context .mark{font-size:70px}.nav .mark{font-size:32px}.small-study{margin-top:21px}}
'''
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>hiraia — Fraunces, books & signals</title><style>@font-face{{font-family:Fraunces;src:url(data:font/woff2;base64,{font}) format('woff2');font-weight:400;}}{css}</style><main><div class="top"><div><span class="mini">hiraia</span><p>Fraunces / chosen typeface</p></div><span class="eyebrow">Study 03 / Book + signal</span></div><h1>A book with a signal.</h1><p class="intro">Three ways to bring the open book and Wi-Fi language into a single raised glyph. The curves are rounded to sit comfortably beside Fraunces and its circular dots.</p><div class="options">{cards}</div><div class="controls"><button id="mono" aria-pressed="false">Toggle single colour</button><label>Glyph size <input id="size" type="range" min="27" max="44" value="34" aria-label="Glyph size"></label><label>Raised position <input id="rise" type="range" min="25" max="65" value="44" aria-label="Glyph raised position"></label><button id="reset">Reset proportions</button></div><p class="status" id="status" aria-live="polite">Selected: Broadcast book</p><div class="tryout"><div class="context dark"><div class="eyebrow">One colour / reversed</div>{mark(cls='chosen')}<p>A small, distinctive signature beside the name.</p></div><div class="context"><div class="eyebrow">In the website header</div><div class="nav">{mark(cls='chosen small')}<span>About&nbsp;&nbsp; Download ↗</span></div><p>Science learning, wherever you are.</p></div></div><footer>My starting choice is <b>Broadcast book</b>: the clearest reading of both ideas. <b>Wave pages</b> is the more abstract route; <b>Open signal</b> gives the strongest small silhouette. Select any option to see it in the header and reversed examples. These are custom SVG studies, ready for further drawing and spacing refinement.</footer></main><script>
const glyphs={json.dumps(glyphs)},names={json.dumps({key:name for key,_,name,*_ in options})};
function choose(key){{document.querySelectorAll('.chosen .glyph').forEach(el=>el.innerHTML=glyphs[key]);document.querySelectorAll('[data-option]').forEach(el=>{{const on=el.dataset.option===key;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));el.querySelector('.choose').textContent=(on?'Selected':'Try this glyph')+' ↗';}});document.getElementById('status').textContent='Selected: '+names[key];}}
document.querySelectorAll('[data-option]').forEach(el=>el.onclick=()=>choose(el.dataset.option));
document.getElementById('mono').onclick=e=>{{let on=document.body.classList.toggle('mono');e.target.setAttribute('aria-pressed',String(on));}};
const size=document.getElementById('size'),rise=document.getElementById('rise');size.oninput=()=>document.body.style.setProperty('--glyph-size',size.value/100+'em');rise.oninput=()=>document.body.style.setProperty('--glyph-rise',-rise.value/100+'em');document.getElementById('reset').onclick=()=>{{size.value=34;rise.value=44;size.oninput();rise.oninput();}};choose('broadcast');
</script></html>'''
(out/'index.html').write_text(html)
print(out/'index.html')
